def write_output(path: Path, rows: list[dict]):
    """Write rows to CSV with RFC 4180 compliance."""
    fieldnames = ["city_id", "city_name", "year", "indicator_id", "indicator_name", "value", "unit"]
    with open(path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, quoting=csv.QUOTE_MINIMAL)
        writer.writeheader()
        for row in rows:
            # Only write fields that are in the output schema
            output_row = {}
            for field in fieldnames:
                output_row[field] = row.get(field, "")
            writer.writerow(output_row)

